String fn0(String p0) {
  final sb = StringBuffer();
  for (int i = 0; i < p0.length; i++) {
    final c = p0.codeUnitAt(i);
    if (c >= 48 && c <= 57) sb.writeCharCode(c);
  }
  if (sb.isEmpty) return 'No digits found';
  final n = int.parse(sb.toString());
  if (n == 0) return 'Digits form 0: not a prime power';
  if (n == 1) return 'Digits form 1: not a prime power';

  bool isPrime(int v) {
    if (v < 2) return false;
    if (v % 2 == 0) return v == 2;
    for (int i = 3; i <= v ~/ i; i += 2) {
      if (v % i == 0) return false;
    }
    return true;
  }

  if (isPrime(n)) return 'Digits form $n: a prime number';

  int p = 0;
  for (int i = 2; i <= n ~/ i; i++) {
    if (n % i == 0) {
      p = i;
      break;
    }
  }
  if (p == 0) return 'Digits form $n: not a prime power';
  int m = n;
  int k = 0;
  while (m % p == 0) {
    m ~/= p;
    k++;
  }
  if (m == 1) return 'Digits form $n: a prime power ($p^$k)';
  return 'Digits form $n: not a prime power';
}

List<List<int>> fn0(List<int> p0) {
