  if (sep < 0) return <List<int>>[];

  final left = p0.sublist(0, sep)..sort();
  final right = p0.sublist(sep + 1);
  final out = <List<int>>[];

  for (final v in right) {
    var lo = 0;
    var hi = left.length;
    while (lo < hi) {
      final mid = (lo + hi) >> 1;
      if (left[mid] < v) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    out.add(<int>[v, lo]);
  }

  return out;
}

