    p0.length,
    (_) => <int>[],
  );
  final List<int> roots = <int>[];

  for (int i = 0; i < p0.length; i++) {
    final int parent = p0[i];
    if (parent < 0) {
      roots.add(i);
    } else {
      children[parent].add(i);
    }
  }

  final Map<String, int> result = <String, int>{};

  int visit(int index) {
    int total = p1[index];
    for (final int child in children[index]) {
      total += visit(child);
    }
    result['acct_$index'] = total;
    return total;
  }

  for (final int root in roots) {
    visit(root);
  }

  return result;
}

double fn0(String p0) {
  final parts = p0.split(',');
  if (parts.length < 2) return 0.0;

  int minutesOf(String s) {
    final h = int.parse(s.substring(0, 2));
    final m = int.parse(s.substring(3, 5));
    return h * 60 + m;
  }

  var total = 0;
  for (var i = 0; i < parts.length - 1; i++) {
    final a = minutesOf(parts[i]);
    final b = minutesOf(parts[i + 1]);
    var d = b - a;
    if (d < 0) d += 24 * 60;
    total += d;
  }

  return total / (parts.length - 1);
}

