  int roundedDown = 0;
  int unchanged = 0;
  int totalAdjustment = 0;
  int gcd = 0;

  for (final amount in p0) {
    final absAmount = amount < 0 ? -amount : amount;

    var a = gcd;
    var b = absAmount;
    while (b != 0) {
      final next = a % b;
      a = b;
      b = next;
    }
    gcd = a;

    final remainder = absAmount % p1;
    if (remainder == 0) {
      unchanged++;
    } else if (remainder * 2 < p1) {
      roundedDown++;
      totalAdjustment -= remainder;
    } else {
      roundedUp++;
      totalAdjustment += p1 - remainder;
    }
  }

  return <String, int>{
    'rounded_up': roundedUp,
    'rounded_down': roundedDown,
    'unchanged': unchanged,
    'total_adjustment': totalAdjustment,
    'gcd': gcd,
  };
}

String fn0(List<String> p0) {
