String fn0(List<String> p0) {
  final Map<String, Map<String, int>> data = {};
  int skipped = 0;
  for (final line in p0) {
    final parts = line.split(':');
    if (parts.length != 3) {
      skipped++;
      continue;
    }
    final id = parts[0];
    final key = parts[1];
    final value = int.tryParse(parts[2]);
    if (value == null) {
      skipped++;
      continue;
    }
    final inner = data.putIfAbsent(key, () => <String, int>{});
    inner[id] = value;
  }

  final List<String> validParts = [];
  final keys = data.keys.toList()..sort();
  for (final key in keys) {
    final inner = data[key]!;
    if (inner.length >= 2) {
      final sum = inner.values.fold<int>(0, (a, b) => a + b);
      validParts.add('$key:$sum');
    } else {
      skipped++;
    }
  }

  if (validParts.isEmpty) return '';

  var result = 'valid: ${validParts.join(',')}';
  if (skipped > 0) {
    result += '; skipped: $skipped';
  }
  return result;
}

